<?php session_start();include 'config.php';if(!isset($_SESSION['doctor_id'])){header('Location:index.php');exit;}$id=(int)$_SESSION['doctor_id'];$s=$conn->prepare('SELECT * FROM doctors WHERE id=?');$s->bind_param('i',$id);$s->execute();$doctor=$s->get_result()->fetch_assoc(); ?>
<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Edit Doctor Profile - MedEase</title><link rel="stylesheet" href="style.css"><style>body{margin:0;background:#f4f7fb;font-family:Arial,sans-serif}.edit{max-width:520px;margin:55px auto;background:#fff;padding:28px;border-radius:20px;box-shadow:0 10px 30px #1e293b18}.edit h2{text-align:center}.field{margin:12px 0}.field label{display:block;font-weight:600;margin-bottom:6px}.field input{width:100%;box-sizing:border-box;padding:11px;border:1px solid #cbd5e1;border-radius:10px}.photo{width:100px;height:100px;border-radius:50%;object-fit:cover;display:block;margin:0 auto 15px}.btn{width:100%;padding:12px;border:0;border-radius:10px;background:#4f46e5;color:#fff;font-weight:700}</style></head><body><div class="edit"><h2>Edit Doctor Profile</h2><?php if(!empty($doctor['profile_photo'])):?><img class="photo" src="<?=htmlspecialchars($doctor['profile_photo'])?>"><?php endif;?><form action="update_doctor_profile.php" method="post" enctype="multipart/form-data"><div class="field"><label>Profile photo</label><input type="file" name="profile_photo" accept="image/jpeg,image/png,image/webp"></div><?php foreach(['full_name'=>'Full name','specialization'=>'Specialization','hospital'=>'Hospital','email'=>'Email','phone'=>'Phone','address'=>'Address'] as $k=>$label):?><div class="field"><label><?=$label?></label><input name="<?=$k?>" value="<?=htmlspecialchars($doctor[$k]??'')?>" required></div><?php endforeach;?><div class="field"><label>Experience (years)</label><input type="number" name="experience" min="0" value="<?=htmlspecialchars($doctor['experience']??0)?>" required></div><button class="btn">Save Profile</button></form></div></body></html>
